      FROM docket_entry e
      WHERE EXISTS (SELECT 1 FROM match_follow)
        AND e.created_at > now() - interval '7 days' AND e.created_at <= now()
        AND e.filed_on IS NOT NULL AND e.filed_on >= (now() - interval '14 days')::date
        AND e.description !~* '\m(seal|seals|sealed|sealing|unseal|unsealed|under seal|ex parte|in camera|grand jury|juvenile|restricted|suppressed|redacted)\M'
