      FROM document d
      WHERE EXISTS (SELECT 1 FROM match_follow)
        AND d.created_at > now() - interval '7 days' AND d.created_at <= now()
        AND d.document_type LIKE '%opinion%'
        AND d.filed_on IS NOT NULL AND d.filed_on >= (now() - interval '30 days')::date
        AND d.title !~* '\m(seal|seals|sealed|sealing|unseal|unsealed|under seal|ex parte|in camera|grand jury|juvenile|restricted|suppressed|redacted)\M'
      UNION ALL
      SELECT 'case:' || c.id, c.id, 'new_case', c.filed_on, NULL::uuid, NULL::uuid, c.updated_at
      FROM legal_case c
      WHERE EXISTS (SELECT 1 FROM match_follow)
        AND c.publication = 'published' AND c.updated_at > now() - interval '7 days' AND c.updated_at <= now()
        AND c.filed_on IS NOT NULL AND c.filed_on >= (now() - interval '30 days')::date
      UNION ALL
      SELECT 'case:' || c.id, c.id, 'new_case', c.filed_on, NULL::uuid, NULL::uuid, a.created_at
      FROM judge_case_assignment a JOIN legal_case c ON c.id = a.case_id
      WHERE EXISTS (SELECT 1 FROM match_follow WHERE kind = 'judge')
        AND a.created_at > now() - interval '7 days' AND a.created_at <= now()
