          OR (f.target_key = 'securities' AND (c.nature_of_suit_code IS NOT NULL AND CASE WHEN substring(c.nature_of_suit_code from '^\s*[0-9]?([0-9]{3})([^0-9]|$)') IS NOT NULL THEN ((substring(c.nature_of_suit_code from '^\s*[0-9]?([0-9]{3})([^0-9]|$)'))::int BETWEEN 850 AND 850) ELSE c.nature_of_suit_code ~* 'securities|commodities' END))
          OR (f.target_key = 'consumer' AND (c.nature_of_suit_code IS NOT NULL AND CASE WHEN substring(c.nature_of_suit_code from '^\s*[0-9]?([0-9]{3})([^0-9]|$)') IS NOT NULL THEN ((substring(c.nature_of_suit_code from '^\s*[0-9]?([0-9]{3})([^0-9]|$)'))::int BETWEEN 480 AND 485) ELSE c.nature_of_suit_code ~* 'consumer credit|telephone consumer' END))
          OR (f.target_key = 'antitrust' AND (c.nature_of_suit_code IS NOT NULL AND CASE WHEN substring(c.nature_of_suit_code from '^\s*[0-9]?([0-9]{3})([^0-9]|$)') IS NOT NULL THEN ((substring(c.nature_of_suit_code from '^\s*[0-9]?([0-9]{3})([^0-9]|$)'))::int BETWEEN 410 AND 410) ELSE c.nature_of_suit_code ~* 'antitrust' END))
          OR (f.target_key = 'immigration' AND (c.nature_of_suit_code IS NOT NULL AND CASE WHEN substring(c.nature_of_suit_code from '^\s*[0-9]?([0-9]{3})([^0-9]|$)') IS NOT NULL THEN ((substring(c.nature_of_suit_code from '^\s*[0-9]?([0-9]{3})([^0-9]|$)'))::int BETWEEN 460 AND 465) ELSE c.nature_of_suit_code ~* 'immigration|naturalization|deportation' END))
          OR (f.target_key = 'social-security' AND (c.nature_of_suit_code IS NOT NULL AND CASE WHEN substring(c.nature_of_suit_code from '^\s*[0-9]?([0-9]{3})([^0-9]|$)') IS NOT NULL THEN ((substring(c.nature_of_suit_code from '^\s*[0-9]?([0-9]{3})([^0-9]|$)'))::int BETWEEN 861 AND 865) ELSE c.nature_of_suit_code ~* 'social security|ssid|diwc|diww|black lung' END))
          OR (f.target_key = 'real-property' AND (c.nature_of_suit_code IS NOT NULL AND CASE WHEN substring(c.nature_of_suit_code from '^\s*[0-9]?([0-9]{3})([^0-9]|$)') IS NOT NULL THEN ((substring(c.nature_of_suit_code from '^\s*[0-9]?([0-9]{3})([^0-9]|$)'))::int BETWEEN 210 AND 290) ELSE c.nature_of_suit_code ~* 'real property|foreclosure|condemnation|ejectment|rent lease' END))
          OR (f.target_key = 'tax' AND (c.nature_of_suit_code IS NOT NULL AND CASE WHEN substring(c.nature_of_suit_code from '^\s*[0-9]?([0-9]{3})([^0-9]|$)') IS NOT NULL THEN ((substring(c.nature_of_suit_code from '^\s*[0-9]?([0-9]{3})([^0-9]|$)'))::int BETWEEN 870 AND 871) ELSE c.nature_of_suit_code ~* 'tax suit' END))
          OR (f.target_key = 'bankruptcy' AND (c.nature_of_suit_code IS NOT NULL AND CASE WHEN substring(c.nature_of_suit_code from '^\s*[0-9]?([0-9]{3})([^0-9]|$)') IS NOT NULL THEN ((substring(c.nature_of_suit_code from '^\s*[0-9]?([0-9]{3})([^0-9]|$)'))::int BETWEEN 422 AND 423) ELSE c.nature_of_suit_code ~* 'bankruptcy' END))
          OR (f.target_key = 'environment' AND (c.nature_of_suit_code IS NOT NULL AND CASE WHEN substring(c.nature_of_suit_code from '^\s*[0-9]?([0-9]{3})([^0-9]|$)') IS NOT NULL THEN ((substring(c.nature_of_suit_code from '^\s*[0-9]?([0-9]{3})([^0-9]|$)'))::int BETWEEN 893 AND 893) ELSE c.nature_of_suit_code ~* 'environmental' END))
          OR (f.target_key = 'government-records' AND (c.nature_of_suit_code IS NOT NULL AND CASE WHEN substring(c.nature_of_suit_code from '^\s*[0-9]?([0-9]{3})([^0-9]|$)') IS NOT NULL THEN ((substring(c.nature_of_suit_code from '^\s*[0-9]?([0-9]{3})([^0-9]|$)'))::int BETWEEN 895 AND 895 OR (substring(c.nature_of_suit_code from '^\s*[0-9]?([0-9]{3})([^0-9]|$)'))::int BETWEEN 899 AND 899) ELSE c.nature_of_suit_code ~* 'freedom of information|administrative procedure' END))
          OR (f.target_key = 'false-claims-fraud' AND (c.nature_of_suit_code IS NOT NULL AND CASE WHEN substring(c.nature_of_suit_code from '^\s*[0-9]?([0-9]{3})([^0-9]|$)') IS NOT NULL THEN ((substring(c.nature_of_suit_code from '^\s*[0-9]?([0-9]{3})([^0-9]|$)'))::int BETWEEN 375 AND 376 OR (substring(c.nature_of_suit_code from '^\s*[0-9]?([0-9]{3})([^0-9]|$)'))::int BETWEEN 470 AND 470) ELSE c.nature_of_suit_code ~* 'false claims|qui tam|racketeer' END))
          OR (f.target_key = 'constitutional' AND (c.nature_of_suit_code IS NOT NULL AND CASE WHEN substring(c.nature_of_suit_code from '^\s*[0-9]?([0-9]{3})([^0-9]|$)') IS NOT NULL THEN ((substring(c.nature_of_suit_code from '^\s*[0-9]?([0-9]{3})([^0-9]|$)'))::int BETWEEN 950 AND 950) ELSE c.nature_of_suit_code ~* 'constitutionality' END)))
    ),
    kept AS (
      SELECT DISTINCT ON (cand.follow_id, cand.item_key)
        cand.follow_id, cand.kind, cand.item_key, cand.case_id, cand.event_kind, cand.occurred_on, cand.event_at,
        CASE cand.event_kind
          WHEN 'new_case' THEN 'New case filed'
          WHEN 'decision' THEN left('Opinion: ' || regexp_replace(d.title, '\s+', ' ', 'g'), 300)
          ELSE CASE WHEN lower(court.provider_court_id) = 'scotus'
            THEN left(regexp_replace(e.description, '\s+', ' ', 'g'), 300)
            ELSE 'New docket entry' END
        END AS summary
      FROM match_candidate cand
      JOIN legal_case c ON c.id = cand.case_id
      JOIN court ON court.id = c.court_id
      LEFT JOIN docket_entry e ON e.id = cand.entry_id
      LEFT JOIN document d ON d.id = cand.document_id
      WHERE (
    c.publication = 'published'
    AND COALESCE((SELECT current_row.displayable FROM publication_current current_row
        WHERE current_row.object_type = 'legal_case' AND current_row.object_id = c.id), (SELECT decision.displayable FROM publication_decision decision
    WHERE decision.object_type = 'legal_case' AND decision.object_id = c.id
    ORDER BY decision.decided_at DESC, decision.id DESC LIMIT 1), false)
    AND c.caption !~* '\m(sealed|under seal|grand jury|juvenile|minor child|in re search|search warrant)\M'
    AND c.docket_number !~* '-(mj|gj|sw|sealed)-'
    AND NOT EXISTS (SELECT 1 FROM direct_court_event restricted_event
      WHERE restricted_event.case_id = c.id AND restricted_event.restricted)
  )
        AND (cand.event_kind <> 'docket_entry' OR (
          e.id IS NOT NULL
          AND NOT EXISTS (SELECT 1 FROM publication_decision restricted_decision
    WHERE restricted_decision.object_type = 'docket_entry' AND restricted_decision.object_id = e.id
      AND NOT restricted_decision.displayable AND restricted_decision.reason_code ~* '(seal|restrict|sensitive|suppress|privacy|minor|juvenile)')
          AND (lower(court.provider_court_id) <> 'scotus' OR COALESCE((SELECT current_row.displayable FROM publication_current current_row
        WHERE current_row.object_type = 'docket_entry' AND current_row.object_id = e.id), (SELECT decision.displayable FROM publication_decision decision
    WHERE decision.object_type = 'docket_entry' AND decision.object_id = e.id
    ORDER BY decision.decided_at DESC, decision.id DESC LIMIT 1), false))))
        AND (cand.event_kind <> 'decision' OR (
          d.id IS NOT NULL AND d.publication = 'published'
          AND COALESCE((SELECT current_row.displayable FROM publication_current current_row
        WHERE current_row.object_type = 'document' AND current_row.object_id = d.id), (SELECT decision.displayable FROM publication_decision decision
    WHERE decision.object_type = 'document' AND decision.object_id = d.id
    ORDER BY decision.decided_at DESC, decision.id DESC LIMIT 1), false)))
      ORDER BY cand.follow_id, cand.item_key, cand.event_at
    ),
    ranked AS (
      SELECT kept.*, row_number() OVER (PARTITION BY kept.follow_id ORDER BY kept.event_at DESC, kept.item_key) AS rn FROM kept
    )
SELECT f.kind, f.label, r.event_kind, r.occurred_on, c.public_id, left(c.caption, 80) AS caption, court.name AS court, r.summary
FROM ranked r JOIN entity_follow f ON f.id = r.follow_id
JOIN legal_case c ON c.id = r.case_id JOIN court ON court.id = c.court_id
WHERE r.rn <= 8
ORDER BY f.kind, f.label, r.rn;

\echo '== live job: stored matches for the test account'
SELECT f.kind, f.label, i.event_kind, count(*) AS stored, count(i.sent_at) AS sent, min(i.found_at) AS first_found, max(i.found_at) AS last_found
FROM entity_alert_item i JOIN entity_follow f ON f.id = i.follow_id JOIN app_user u ON u.id = f.user_id
WHERE u.email = 'alerts-qa@example.com'
GROUP BY 1, 2, 3 ORDER BY 1, 2, 3;

\echo '== live job: cursors and all follows'
SELECT source, scanned_to, now() - scanned_to AS lag FROM entity_alert_cursor ORDER BY source;
SELECT kind, frequency, count(*) AS follows FROM entity_follow GROUP BY 1, 2 ORDER BY 1, 2;
SELECT count(*) AS items, count(*) FILTER (WHERE sent_at IS NULL) AS queued FROM entity_alert_item;
